	        for (const key in data) {
	            const item = data[key];
	            if (item.id !== undefined) {
	                const fieldid = item.id;
	                delete item.id;
	                await TemplateParam.update({ ...item }, { where: { id: fieldid } });
	            } else {
	                await TemplateParam.create({ ...item });
	            }
	        }

	        return { result: true };
