	        // они прокидываются сквозным образом через queryDto и не актуальны для данного сервиса
	        const cleanedOptions = await PageQueryDto.cleanCheckOptions(
	            options.filter ?? {}
	        );

	        return this.getPage(id, { filter: cleanedOptions });
