var Overloads_class;
var hasRequiredOverloads_class;

function requireOverloads_class () {
	if (hasRequiredOverloads_class) return Overloads_class;
	hasRequiredOverloads_class = 1;
	const MetadataClass = requireMetadata_service();
	const Metadata = new MetadataClass();

	const Extensions = requireExtensions_class();

	class OverloadsClass extends Extensions {
	    async prepareOptionsAfter(innerResult, functionParams) {
	        const fthis = functionParams.this;
	        functionParams._args[1];
	        const treeObject = functionParams._args[2];

	        if (!fthis.isProcessing) {
	            return innerResult;
	        }

	        for (const field in treeObject.Fields) {
	            const val = treeObject.Fields[field];

	            val.value = null;

	            const [processing] = Object.values(fthis.tableInfo.Processing);

	            if (val.field === processing.TimeDimension.nameField) {
	                val.value = 'date';
	            }
	        }

	        return innerResult;
	    }

	    async getEntityAfter(innerResult, functionParams) {
	    const fthis = functionParams.this;

	    if (!fthis.isProcessing) { return innerResult; }

	    const [processingId] = Object.keys(fthis.tableInfo.Processing);

	    const entity = await Metadata.getParentInstance(processingId);

	    return { id: processingId, entity };
	}
	}

	Overloads_class = OverloadsClass;
	return Overloads_class;
}

var worker_code_service;
var hasRequiredWorker_code_service;

function requireWorker_code_service () {
	if (hasRequiredWorker_code_service) return worker_code_service;
	hasRequiredWorker_code_service = 1;
	const { Worker, SHARE_ENV, isMainThread, parentPort, workerData } = require$$0$v;

	class worker_codeService {
	    constructor(fileOrCode) {
	        this.file = fileOrCode;
	    }

	    run(func, ...args) {
	        return new Promise((resolve, reject) => {
	            const worker = new Worker(this.file, { workerData: { func, args } });
	            worker.on('message', (result) => {
	                if (result.error) {
	                    reject(result.error);
	                } else {
	                    resolve(result);
	                }
	            });
	            worker.on('error', reject);
	            worker.on('exit', (code) => {
	                if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
	            });
	        });
	    }

	    //НЕ ПРОВЕРЕНО НА РАБОТОСПОСОБНОСТЬ
	    start(code, ...args) {
	        return new Promise((resolve, reject) => {
	            const worker = new Worker(this.file, {
	                workerData: { func, args },
	                eval: true,
	                env: SHARE_ENV,
	            });
	            worker.on('message', resolve);
	            worker.on('error', reject);
	            worker.on('exit', (code) => {
	                if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
	            });
	        });
	    }
	}

	worker_code_service = worker_codeService;
	return worker_code_service;
}

